const { withAppBuildGradle } = require('@expo/config-plugins');

/**
 * Wires android/app/build.gradle's release build type to a real release
 * keystore, read from Gradle properties (MYAPP_UPLOAD_STORE_FILE/
 * MYAPP_UPLOAD_STORE_PASSWORD/MYAPP_UPLOAD_KEY_ALIAS/MYAPP_UPLOAD_KEY_PASSWORD)
 * instead of the auto-generated debug keystore that Expo/RN's template
 * ships by default -- which Google Play rejects.
 *
 * android/ is regenerated by `expo prebuild` (see AGENTS.md: never hand-edit
 * it), so this can't just be a one-off manual edit to build.gradle -- it has
 * to be a config plugin that re-applies on every prebuild. The actual
 * keystore file and its passwords never go through app.json, this plugin,
 * or git: they live only in the machine-level ~/.gradle/gradle.properties.
 *
 * Falls back to the debug keystore whenever those properties aren't set,
 * so the project still builds for anyone without release credentials
 * configured (CI, another contributor, a fresh checkout).
 */
const SIGNING_CONFIG_BLOCK = `
        release {
            if (project.hasProperty('MYAPP_UPLOAD_STORE_FILE')) {
                storeFile file(MYAPP_UPLOAD_STORE_FILE)
                storePassword MYAPP_UPLOAD_STORE_PASSWORD
                keyAlias MYAPP_UPLOAD_KEY_ALIAS
                keyPassword MYAPP_UPLOAD_KEY_PASSWORD
            }
        }
`;

module.exports = function withReleaseSigning(config) {
  return withAppBuildGradle(config, (config) => {
    if (config.modResults.language !== 'groovy') {
      throw new Error('withReleaseSigning: expected android/app/build.gradle to be Groovy, got ' + config.modResults.language);
    }

    let contents = config.modResults.contents;

    if (!contents.includes('MYAPP_UPLOAD_STORE_FILE')) {
      contents = contents.replace(/signingConfigs\s*\{/, (match) => `${match}${SIGNING_CONFIG_BLOCK}`);
    }

    contents = contents.replace(
      /(release\s*\{[^}]*?)signingConfig signingConfigs\.debug/,
      (_match, prefix) =>
        `${prefix}signingConfig project.hasProperty('MYAPP_UPLOAD_STORE_FILE') ? signingConfigs.release : signingConfigs.debug`
    );

    config.modResults.contents = contents;
    return config;
  });
};
